const sites = [
  { name: 'Main Website', url: 'https://example.com' },
  { name: 'API Server', url: 'https://api.example.com/health' },
  { name: 'Dashboard', url: 'https://dashboard.example.com' }
];
return sites.map(s => ({ json: s }));

const items = $input.all();
const results = [];
for (const item of items) {
  const statusCode = item.json.statusCode || item.json.$response?.statusCode || 0;
  const isDown = statusCode < 200 || statusCode >= 400;
  const responseTime = item.json.$response?.responseTime || 0;
  results.push({
    json: {
      name: item.json.name || 'Unknown',
      url: item.json.url || '',
      statusCode,
      isDown,
      responseTime,
      status: isDown ? 'DOWN' : 'UP',
      timestamp: new Date().toISOString(),
      date: new Date().toISOString().split('T')[0]
    }
  });
}
return results;

